import {createHash} from 'node:crypto';

/** Call only with the authoritative /matches/{matchId} document ID, never UI names. */
export function battleIdForMatch(matchId: string): string {
  if (!matchId || matchId.includes('/')) throw new Error('Expected an authoritative Match document ID');
  return matchId;
}

function identity(parts: (string | null)[]): Digest {
  return createHash('sha256').update(JSON.stringify(parts), 'utf8').digest('hex');
}

export function invitationSlotId(battleId: Id, respondentPlayerId: Id): Digest {
  battleIdForMatch(battleId);
  if (!respondentPlayerId) throw new Error('Missing respondent');
  return identity([SOCIAL_V1_CONTRACT, 'INVITATION', battleId, respondentPlayerId]);
}

export function chronicleSceneId(battleId: Id, ownerPlayerId: Id, counterpartPlayerId: Id | null): Digest {
  battleIdForMatch(battleId);
  if (!ownerPlayerId || counterpartPlayerId === '') throw new Error('Missing scene participant');
  return identity([SOCIAL_V1_CONTRACT, 'SCENE', battleId, ownerPlayerId, counterpartPlayerId]);
}

/** Registry entries are server-resolved approvals, never caller-supplied trust. */
export function assertApproved(policy: PolicyRef, approvals: readonly PolicyRef[]): void {
  if (policy.status !== 'APPROVED' || !policy.approvalRef || !approvals.some(p =>
    p.status === 'APPROVED' && p.policyVersion === policy.policyVersion &&
    p.configurationVersion === policy.configurationVersion && p.approvalRef === policy.approvalRef)) {
    throw new Error('Unapproved policy/configuration');
  }
}

export type Publishable = Receipt | Opportunity | PersonalityProfile | PublicClaim | PublicJudgment | RecognitionCandidate;
export function assertPublicationAllowed(record: Publishable, approvals: readonly PolicyRef[]): void {
  const policy = 'selectorPolicy' in record ? record.selectorPolicy :
    'qualificationPolicy' in record ? record.qualificationPolicy : record.policy;
  assertApproved(policy, approvals);
  if ('sliders' in record && record.sliders.some(s => s.status === 'DEVELOPING' && s.value !== null))
    throw new Error('Developing sliders have no value');
  if ('state' in record && record.state === 'SUPERSEDED') throw new Error('Superseded receipt');
  if ('slotId' in record && record.state === 'WITHDRAWN') throw new Error('Withdrawn opportunity');
}

/** Run after canonical schema validation; these constraints compare field values. */
export function assertRecordInvariants<K extends RecordType>(kind: K, value: SocialV1Records[K]): void {
  const v = value as unknown as Record<string, any>;
  if ('battleId' in v && battleIdForMatch(v.matchId) !== v.battleId) throw new Error('Battle/Match identity mismatch');
  if (kind === 'Opportunity' || kind === 'InvitationSlot') {
    if (v.slotId !== invitationSlotId(v.battleId, v.respondentPlayerId)) throw new Error('Invalid slot identity');
  }
  if (kind === 'ChronicleScene' && v.sceneId !== chronicleSceneId(v.battleId, v.ownerPlayerId, v.counterpartPlayerId))
    throw new Error('Invalid scene identity');
  if (kind === 'SourceSnapshot') {
    const players = v.roster.map((r: any) => r.playerId), slots = v.roster.map((r: any) => r.replaySlot);
    if (new Set(players).size !== players.length || new Set(slots).size !== slots.length)
      throw new Error('Roster mapping must be one-to-one');
    if (v.outcome.winningPlayerIds?.some((id: string) => !players.includes(id))) throw new Error('Winner outside roster');
    if (new Set(v.artifactRefs.map((r: any) => r.kind)).size !== v.artifactRefs.length) throw new Error('Duplicate artifact kind');
    if (!v.artifactRefs.some((r: any) => r.kind === 'STATISTICS')) throw new Error('Missing statistics artifact');
  }
  if (v.subject?.system === 'RELATIONSHIP' && v.subject.fromPlayerId === v.subject.toPlayerId)
    throw new Error('Relationship requires two players');
  if (kind === 'Inference' && v.action.actorPlayerId === v.action.counterpartPlayerId) throw new Error('Inference requires two players');
  if (kind === 'Judgment' && new Set(v.choices.map((c: any) => c.choiceId)).size !== v.choices.length)
    throw new Error('Duplicate judgment choice');
  if (kind === 'Receipt' && v.allocatedUnits !== null && v.requestedUnits !== null && v.allocatedUnits > v.requestedUnits)
    throw new Error('Allocation exceeds request');
}

/** Privacy projection: pending siblings, meaning refs, notes and audit never escape. */
export function publicJudgment(j: Judgment, approvals: readonly PolicyRef[]): PublicJudgment | null {
  assertApproved(j.qualificationPolicy, approvals);
  if (j.correction === 'REOPENED' || j.correction === 'SUPERSEDED') return null;
  const choices: PublicJudgment['choices'] = [];
  for (const c of j.choices) {
    if (c.decision === 'QUALIFIED') choices.push({choiceId:c.choiceId, decision:c.decision, label:'Qualified'});
    if (c.decision === 'NOT_QUALIFIED') choices.push({choiceId:c.choiceId, decision:c.decision, label:'Not Qualified — No Relationship Effect'});
  }
  if (!choices.length) return null;
  return {judgmentId:j.judgmentId, judgmentRevision:j.judgmentRevision, incidentId:j.incidentId,
    incidentRevision:j.incidentRevision, sourceAuthority:j.sourceAuthority, authorPlayerId:j.authorPlayerId,
    counterpartPlayerId:j.counterpartPlayerId, family:j.family, qualificationPolicy:j.qualificationPolicy, choices};
}

/** Pure transaction plan. Persist by create-if-absent/CAS inside one server transaction.
 * Never delete a consumed slot, even when its selected evidence is withdrawn. */
export function planInvitationOffer(current: InvitationSlot | null, opportunity: Opportunity,
  expectedRevision: number, approvals: readonly PolicyRef[]): {slot: InvitationSlot; created: boolean} {
  assertPublicationAllowed(opportunity, approvals);
  const slotId = invitationSlotId(opportunity.battleId, opportunity.respondentPlayerId);
  if (opportunity.matchId !== opportunity.battleId || opportunity.slotId !== slotId || opportunity.state !== 'OFFERED')
    throw new Error('Invalid invitation identity/state');
  if ((current?.revision ?? 0) !== expectedRevision) throw new Error('Invitation revision changed');
  if (current) {
    assertSlotIdentity(current);
    if (current.slotId !== slotId) throw new Error('Different invitation slot');
    if (current.state !== 'WITHDRAWN' && current.currentOpportunityRevision === opportunity.opportunityRevision)
      return {slot:current, created:false};
    throw new Error('Battle invitation already consumed');
  }
  return {created:true, slot:{slotId, battleId:opportunity.battleId, matchId:opportunity.matchId,
    respondentPlayerId:opportunity.respondentPlayerId, revision:1, state:'OFFERED',
    firstOpportunityRevision:opportunity.opportunityRevision, currentOpportunityRevision:opportunity.opportunityRevision}};
}

function assertSlotIdentity(slot: InvitationSlot): void {
  if (slot.matchId !== slot.battleId || slot.slotId !== invitationSlotId(slot.battleId, slot.respondentPlayerId))
    throw new Error('Invalid slot identity');
}

export function transitionInvitation(slot: InvitationSlot, expectedRevision: number,
  opportunityRevision: Digest, next: Exclude<InvitationSlot['state'], 'OFFERED'>): InvitationSlot {
  assertSlotIdentity(slot);
  if (slot.revision !== expectedRevision || slot.currentOpportunityRevision !== opportunityRevision)
    throw new Error('Stale invitation');
  const allowed: Record<InvitationSlot['state'], string[]> = {OFFERED:['DEFERRED','DECLINED','SUBMITTED','WITHDRAWN'],
    DEFERRED:['DECLINED','SUBMITTED','WITHDRAWN'], DECLINED:['WITHDRAWN'], SUBMITTED:['WITHDRAWN'], WITHDRAWN:[]};
  if (!allowed[slot.state].includes(next)) throw new Error('Invalid invitation transition');
  return {...slot, revision:slot.revision + 1, state:next,
    currentOpportunityRevision:next === 'WITHDRAWN' ? null : slot.currentOpportunityRevision};
}
